'use strict';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const icon=n=>`<svg aria-hidden="true"><use href="#${n}"/></svg>`;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function read(k,d){try{return JSON.parse(localStorage.getItem(k))??d}catch{return d}}
function write(k,v){try{localStorage.setItem(k,JSON.stringify(v))}catch{toast('Не удалось сохранить: хранилище браузера заполнено')}}
let state={color:'#ff9e57',brightness:75,speed:35,power:true,effect:'static',scene:'warm',...read('luma-state',{})};
const scenes=[{id:'warm',name:'Тёплый вечер',sub:'Уют в каждом оттенке',color:'#ff9e57',brightness:75,effect:'static',icon:'sun'},{id:'romance',name:'Романтика',sub:'Мягко. Нежно. Вдвоём.',color:'#f47493',brightness:45,effect:'breathe',icon:'heart'},{id:'intimate',name:'Для двоих',sub:'Только ваш момент',color:'#ce436b',brightness:25,effect:'breathe',icon:'heart'},{id:'party',name:'Тусовка',sub:'Больше цвета и энергии',color:'#a484ff',brightness:85,effect:'rainbow',icon:'music'},{id:'cinema',name:'Кино',sub:'Ничего лишнего',color:'#7394e9',brightness:20,effect:'static',icon:'moon'},{id:'night',name:'Ночной свет',sub:'Время замедлиться',color:'#ffd08b',brightness:8,effect:'static',icon:'moon'}];
let customScenes=read('luma-scenes',[]), rooms=read('luma-rooms',['Гостиная','Спальня','Кухня']);
let selectedRoom='Все комнаты',deviceRoom=read('luma-device-room','Гостиная'),cameras=read('luma-cameras',[]);
let connection={mode:'demo',url:'',...read('luma-connection',{})}, connected=false, page='light',control='color';
let apiToken=sessionStorage.getItem('luma-token')||'',timerEnd=connection.mode==='demo'?read('luma-timer',0):0,micStream=null,audioContext=null,analyser=null,audioSource=null,audioActive=false,audioLevel=0;
let lastAudioSend=0,sendTimer=null,requestBusy=false,pendingState=null,connectionEpoch=0,toastTimer;
const effects=[['static','Постоянный свет'],['breathe','Дыхание'],['rainbow','Перелив цветов'],['candle','Свеча']];
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3600)}
function rgb(hex){return hex.match(/[a-f\d]{2}/gi).map(x=>parseInt(x,16))}
function hsv(h,s=0.66,v=1){let f=n=>{let k=(n+h/60)%6;return Math.round(255*v*(1-s*Math.max(0,Math.min(k,4-k,1))))};return '#'+[f(5),f(3),f(1)].map(v=>v.toString(16).padStart(2,'0')).join('')}
function hue(hex){let [r,g,b]=rgb(hex).map(x=>x/255),max=Math.max(r,g,b),d=max-Math.min(r,g,b);if(!d)return 0;return (((max===r?(g-b)/d:max===g?(b-r)/d+2:(r-g)/d+4)*60)+360)%360}
function persist(){write('luma-state',state)}
function activeScene(){return [...scenes,...customScenes].find(s=>s.id===state.scene)}
function update(){document.documentElement.style.setProperty('--light',state.color);$('#hex').value=state.color.toUpperCase();$('#nativeColor').value=state.color;$('#brightness').value=state.brightness;$('#brightnessValue').innerHTML=state.brightness+'<span>%</span>';$('#speed').value=state.speed;$('#speedValue').textContent=state.speed+'%';$('#power').classList.toggle('off',!state.power);$('#power').setAttribute('aria-pressed',state.power);$('#power').setAttribute('aria-label',state.power?'Выключить подсветку':'Включить подсветку');$('#stageLabel').textContent=state.power?(activeScene()?.name||'Мой свет'):'Свет выключен';$('#colorName').textContent=state.color==='#ff9e57'?'Тёплый янтарь':state.color.toUpperCase();$('#colorDot').style.background=state.color;const h=hue(state.color),angle=h*Math.PI/180,radius=($('#colorWheel').clientWidth||157)/2-10;$('#wheelHandle').style.transform=`translate(calc(-50% + ${Math.sin(angle)*radius}px),calc(-50% - ${Math.cos(angle)*radius}px))`;$('#colorWheel').setAttribute('aria-valuenow',Math.round(h));$$('.scene-card').forEach(el=>{el.classList.toggle('active',el.dataset.scene===state.scene);el.setAttribute('aria-pressed',el.dataset.scene===state.scene)});$$('.swatch').forEach(el=>el.classList.toggle('active',el.dataset.color===state.color));$$('.effect-option').forEach(el=>el.classList.toggle('selected',el.dataset.effect===state.effect));$('.speed-block').classList.toggle('visible',control==='effects'&&state.effect!=='static');$('#artRoom').textContent=deviceRoom.toUpperCase();$('#picture').style.filter=state.power?'none':'brightness(.65)';persist()}
function change(patch){state={...state,...patch};update();queueSend()}
function selectScene(id){let s=[...scenes,...customScenes].find(s=>s.id===id);if(!s)return;stopAudio();change({color:s.color,brightness:s.brightness,speed:s.speed||35,effect:s.effect,scene:id,power:true});toast(s.name+' · '+(connection.mode==='demo'?'предпросмотр':'отправка на устройство'))}
function renderScenes(el){el.innerHTML=[...scenes,...customScenes].map(s=>`<button class="scene-card ${s.id===state.scene?'active':''}" data-scene="${esc(s.id)}" aria-pressed="${s.id===state.scene}" style="--scene-color:${/^#[a-f\d]{6}$/i.test(s.color)?s.color:'#ffffff'}"><span class="scene-tick">${icon('check')}</span><span class="scene-orb">${icon(s.icon||'scene')}</span><h3>${esc(s.name)}</h3><p>${esc(s.sub||'Ваша атмосфера')}</p></button>`).join('')}
function renderRooms(){ $('#rooms').innerHTML=rooms.map(r=>`<button class="room-button ${r===deviceRoom?'selected':''}" data-room="${esc(r)}"><i></i>${esc(r)}</button>`).join('');$('#roomTabs').innerHTML=['Все комнаты',...rooms].map(r=>`<button data-room="${esc(r)}" class="${selectedRoom===r?'active':''}">${esc(r)}${r==='Все комнаты'||r===deviceRoom?'<span>1</span>':''}</button>`).join('') }
function renderConnection(){let label=connection.mode==='demo'?'Демо-режим':connected?'ESP8266 подключён':'Нет соединения';$('#connectionBadge').innerHTML='<i></i>'+label;$('#bottomStatus').textContent=connection.mode==='demo'?'Предпросмотр · оборудование не подключено':connected?'Команды подтверждены ESP8266':'Устройство недоступно · изменения только в превью';$('#connectionBadge i').style.background=connected?'#a6ba90':'#edb98a'}
function apiBase(){if(connection.mode==='local')return '';return connection.url.replace(/\/$/,'')}
async function api(path,body){if(connection.mode==='demo')throw new Error('Демо-режим');let base=apiBase();if(connection.mode==='gateway'){let u=new URL(base);if(u.protocol!=='https:')throw new Error('Для онлайн-версии нужен HTTPS-шлюз')}if(connection.mode==='local'&&location.protocol==='https:')throw new Error('Откройте интерфейс по IP вашего ESP8266 в локальной сети');const controller=new AbortController(),timeout=setTimeout(()=>controller.abort(),4500);try{let res=await fetch(base+path,{method:body?'POST':'GET',headers:{'X-API-Key':apiToken,...(body?{'Content-Type':'application/x-www-form-urlencoded'}:{})},body:body?new URLSearchParams(body):undefined,signal:controller.signal});if(!res.ok)throw new Error(res.status===401?'Неверный ключ устройства':'Ошибка устройства: '+res.status);let result=await res.json();if(result.device!=='luma-esp8266')throw new Error('Адрес не является Luma ESP8266');return result}finally{clearTimeout(timeout)}}
async function connect(){if(connection.mode==='demo'){connected=false;renderConnection();return}try{const remote=await api('/api/state');connected=true;state={...state,color:remote.color,brightness:remote.brightness,speed:remote.speed,effect:remote.effect,power:remote.power,scene:''};timerEnd=remote.remaining?Date.now()+remote.remaining*1000:0;write('luma-timer',timerEnd);update();renderConnection();toast('ESP8266 подключён · состояние загружено')}catch(e){connected=false;renderConnection();toast(e.name==='AbortError'?'Устройство не отвечает':e.message)}}
function queueSend(){if(connection.mode==='demo')return;clearTimeout(sendTimer);sendTimer=setTimeout(()=>{pendingState={color:state.color.slice(1),brightness:state.brightness,speed:state.speed,effect:state.effect,power:state.power?1:0};flush()},100)}
async function flush(){if(requestBusy||!pendingState)return;const data=pendingState;pendingState=null;requestBusy=true;const epoch=connectionEpoch;try{await api('/api/state',data);if(epoch===connectionEpoch){connected=true;renderConnection()}}catch(e){if(epoch===connectionEpoch){connected=false;renderConnection();toast('Команда не доставлена. Проверьте подключение.')}}finally{requestBusy=false;if(pendingState)flush()}}
function openModal(title,body,submit,label='Сохранить'){ $('#modalTitle').textContent=title;$('#modalBody').innerHTML=body;$('#modalSubmit').textContent=label;$('#modalForm').onsubmit=async e=>{e.preventDefault();let btn=$('#modalSubmit');btn.disabled=true;try{if(await submit(new FormData(e.target))!==false)$('#modal').close()}catch(err){toast(err.message)}finally{btn.disabled=false}};$('#modal').showModal() }
$('#closeModal').onclick=$('#cancelModal').onclick=()=>$('#modal').close();$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close()}});
function saveScene(){openModal('Ваша световая сцена',`<label class="field">Название<input name="name" placeholder="Например, воскресный вечер" maxlength="32" required autofocus></label><p>Сохраним текущий цвет, яркость, эффект и скорость.</p>`,fd=>{let name=fd.get('name').trim();if(!name){toast('Введите название');return false}customScenes.push({...state,id:'custom-'+Date.now(),name,sub:'Ваша атмосфера',icon:'scene'});write('luma-scenes',customScenes);renderScenes($('#sceneGrid'));if(page==='scenes')showPage('scenes');toast('Сцена сохранена')})}
function addDevice(){openModal('Добавить устройство',`<label class="field">Тип устройства<select name="type"><option value="light">RGB-подсветка · ESP8266</option><option value="camera">Камера наблюдения</option></select></label><p>Подключите подсветку картины или добавьте камеру по адресу видеопотока.</p>`,fd=>{setTimeout(()=>fd.get('type')==='camera'?cameraModal():showPage('settings'),30)},'Продолжить')}
function cameraModal(){openModal('Подключить камеру',`<div class="settings-grid"><label class="field">Название<input name="name" placeholder="Камера в гостиной" maxlength="50" required></label><label class="field">Формат<select name="type"><option value="mjpeg">MJPEG / обновляемое изображение</option><option value="video">MP4 / WebM видеопоток</option></select></label><label class="field">Адрес потока<input name="url" type="url" placeholder="https://camera.example/stream" required><small>RTSP напрямую не поддерживается браузером. Используйте шлюз в MJPEG или совместимый браузерный поток. Для HTTPS-приложения нужен HTTPS-адрес камеры.</small></label><label class="field">Комната<select name="room">${rooms.map(r=>`<option>${esc(r)}</option>`).join('')}</select></label></div>`,fd=>{let u=new URL(fd.get('url'));if(!['http:','https:'].includes(u.protocol)||(location.protocol==='https:'&&u.protocol!=='https:')){toast('Укажите совместимый HTTP(S)-адрес; на HTTPS нужен HTTPS');return false}if(u.username||u.password){toast('Используйте адрес без пароля в URL, через защищённый шлюз');return false}cameras.push({id:Date.now(),name:fd.get('name').trim(),type:fd.get('type'),url:u.href,room:fd.get('room')});write('luma-cameras',cameras);showPage('cameras');toast('Камера добавлена. Проверяем поток…')},'Добавить')}
const heading=(title,desc,action='')=>`<div class="page-heading"><div><div class="eyebrow">МОЙ ДОМ / ${title.toUpperCase()}</div><h1>${title}</h1><p>${desc}</p></div>${action}</div>`;
function showPage(next){if(next!=='light')stopAudio();page=next;document.body.classList.remove('focus-mode');const names={light:'Освещение',overview:'Обзор',cameras:'Камеры',scenes:'Сценарии',timer:'Таймер',settings:'Настройки'};$('#crumb').textContent=names[next];$$('nav [data-page]').forEach(x=>x.classList.toggle('active',x.dataset.page===next));$('#lightPage').hidden=next!=='light';$('#otherPage').hidden=next==='light';let el=$('#otherPage');if(next==='light')return;
if(next==='overview'){el.innerHTML=heading('Мой дом','Всё важное — в одном пространстве.',`<button class="button secondary" id="overviewAdd">${icon('plus')}Добавить устройство</button>`)+`<div class="content-panel"><h2>Устройства</h2><div class="device-row"><div>Подсветка картины<small>${esc(deviceRoom)} · RGB / ESP8266 · ${connection.mode==='demo'?'демонстрация':connected?'подключено':'нет соединения'}</small></div><button class="button secondary" data-page="light">Управлять ${icon('arrow')}</button></div><div class="device-row"><div>Камеры наблюдения<small>${cameras.length?cameras.length+' добавлено':'Пока нет камер'}</small></div><button class="button secondary" data-page="cameras">Открыть ${icon('arrow')}</button></div></div><div class="content-panel"><h2>Комнаты</h2><p>${rooms.map(esc).join(' · ')}</p><div class="note">${connection.mode==='demo'?'Сейчас работает интерактивное превью. Подключите ESP8266 в настройках, чтобы управлять настоящим светом.':'Статус показывает доступность контроллера. Проверьте соединение перед управлением.'}</div><button class="button secondary" data-page="settings">${icon('wifi')}Настроить подключение</button></div>`;$('#overviewAdd').onclick=addDevice}
if(next==='scenes'){el.innerHTML=heading('Сценарии','Сохраните настроение и возвращайтесь к нему одним касанием.',`<button class="button secondary" id="newScene">${icon('plus')}Своя сцена</button>`)+`<div class="scene-grid scene-library" id="sceneLibrary"></div>`+(customScenes.length?'<div class="content-panel"><h2>Мои сцены</h2>'+customScenes.map(s=>`<div class="device-row"><span>${esc(s.name)}</span><button class="delete" data-delete-scene="${esc(s.id)}">Удалить</button></div>`).join('')+'</div>':'');renderScenes($('#sceneLibrary'));$('#newScene').onclick=saveScene}
if(next==='cameras'){el.innerHTML=heading('Камеры','Ваш дом в поле зрения.',`<button class="button secondary" id="newCamera">${icon('plus')}Добавить камеру</button>`)+(cameras.length?`<div class="camera-grid">${cameras.map(c=>`<article class="camera-tile">${c.type==='mjpeg'?`<img class="camera-media" src="${esc(c.url)}" alt="Поток: ${esc(c.name)}" data-cam="${c.id}">`:`<video class="camera-media" src="${esc(c.url)}" controls muted playsinline data-cam="${c.id}"></video>`}<div class="device-row"><div>${esc(c.name)}<small id="camStatus${c.id}">${esc(c.room)} · подключение…</small></div><button class="delete" data-delete-camera="${c.id}">Удалить</button></div></article>`).join('')}</div>`:`<div class="content-panel empty-state">${icon('camera')}<h2>Первый взгляд на ваш дом</h2><p>Подключите IP-камеру по адресу совместимого потока. Здесь появится изображение с вашей камеры.</p><button class="button primary" id="emptyCamera">Подключить камеру</button></div>`);$('#newCamera').onclick=cameraModal;if($('#emptyCamera'))$('#emptyCamera').onclick=cameraModal;$$('[data-cam]').forEach(media=>{const c=cameras.find(c=>c.id===+media.dataset.cam);media.addEventListener(c.type==='mjpeg'?'load':'loadeddata',()=>$('#camStatus'+c.id).textContent=c.room+' · поток загружен');media.addEventListener('error',()=>$('#camStatus'+c.id).textContent='Поток недоступен · проверьте адрес и формат')})}
if(next==='timer'){el.innerHTML=heading('Таймер сна','Выключите свет вовремя. Оставайтесь в моменте.')+`<div class="content-panel"><h2>Выключить подсветку через</h2><div class="timer-display" id="timerCountdown">—</div><div class="timer-presets">${[15,30,60,120].map(n=>`<button data-minutes="${n}">${n} мин</button>`).join('')}</div><form id="timerForm"><div class="form-pair"><label class="field">Своё время, в минутах<input type="number" name="minutes" min="1" max="1440" value="45" required></label><button class="button primary" type="submit">Запустить таймер</button></div></form><p id="timerHint">${connection.mode==='demo'?'В деморежиме таймер работает, пока открыта эта вкладка.':'Таймер отправляется в ESP8266 и работает без открытой вкладки. При перезагрузке контроллера сбрасывается.'}</p><button class="button secondary" id="cancelTimer" style="margin-top:20px">Отменить таймер</button></div>`;$('#timerForm').onsubmit=e=>{e.preventDefault();startTimer(+new FormData(e.target).get('minutes'))};$('#cancelTimer').onclick=()=>startTimer(0);updateTimer()}
if(next==='settings'){el.innerHTML=heading('Настройки','Подключение устройств и ваше пространство.')+`<form id="settingsForm" class="content-panel"><h2>Контроллер подсветки</h2><div class="settings-grid"><label class="field">Режим подключения<select name="mode" id="modeSelect"><option value="demo">Демонстрация — без оборудования</option><option value="local">Локально — приложение на ESP8266</option><option value="gateway">Удалённо — через HTTPS-шлюз</option></select></label><label class="field">Адрес HTTPS-шлюза<input type="url" name="url" placeholder="https://home.example.com" value="${esc(connection.url)}"><small>Шлюз должен передавать /api/state и /api/timer в ESP8266 и разрешать CORS для этого приложения.</small></label><label class="field">Ключ API устройства<input type="password" name="token" autocomplete="off" placeholder="Ключ из config.h" value="${esc(apiToken)}"><small>Ключ хранится только на время сессии браузера. Не открывайте ESP8266 напрямую в интернет.</small></label><label class="field">Комната картины<select name="room">${rooms.map(r=>`<option ${r===deviceRoom?'selected':''}>${esc(r)}</option>`).join('')}</select></label></div><div class="note">Для локального управления загрузите прошивку и интерфейс в ESP8266, затем откройте его IP в домашней Wi-Fi сети. Онлайн-версия не может обращаться к обычному HTTP-контроллеру без защищённого шлюза.</div><button class="button primary" type="submit">Сохранить и проверить</button></form><div class="content-panel"><h2>Прошивка и подключение</h2><p>Arduino / ESP8266, обычная аналоговая RGB-лента, три PWM-канала. Сцены, плавные эффекты, API и автономный таймер.</p><div class="note">RGB-ленту нельзя подключать напрямую к GPIO. Нужны 3 логических MOSFET, отдельный блок питания под напряжение ленты и общая земля. Подробная схема — в инструкции.</div><a class="button secondary" href="https://luma-home-atelier-d25.abloomgnome257.chatgpt.site/luma-esp8266.zip" download>↓ Скачать комплект ESP8266</a> <a class="button secondary" href="guide.html" target="_blank" rel="noopener">Инструкция ↗</a></div>`;$('#modeSelect').value=connection.mode;$('#settingsForm').onsubmit=async e=>{e.preventDefault();let fd=new FormData(e.target),mode=fd.get('mode'),url=fd.get('url').trim();if(mode==='gateway'){try{let u=new URL(url);if(u.protocol!=='https:')throw 0}catch{toast('Введите HTTPS-адрес шлюза');return}}if(mode==='local'&&location.protocol==='https:'){toast('Локальный режим: откройте приложение по IP ESP8266');return}connectionEpoch++;pendingState=null;clearTimeout(sendTimer);connection={mode,url};apiToken=fd.get('token');sessionStorage.setItem('luma-token',apiToken);write('luma-connection',connection);deviceRoom=fd.get('room');write('luma-device-room',deviceRoom);renderRooms();update();await connect();if(mode==='demo')toast('Настройки сохранены · деморежим')}} }
async function startTimer(minutes){if(connection.mode!=='demo'){try{await api('/api/timer',{minutes});connected=true}catch{connected=false;renderConnection();toast('Таймер не установлен: ESP8266 недоступен');return}}timerEnd=minutes?Date.now()+minutes*60000:0;write('luma-timer',timerEnd);updateTimer();toast(minutes?'Таймер на '+minutes+' мин установлен':'Таймер отменён')}
function updateTimer(){let remaining=Math.max(0,Math.ceil((timerEnd-Date.now())/1000));$('#timerLabel').textContent=remaining?'Выключение через '+Math.ceil(remaining/60)+' мин':'Таймер не задан';if($('#timerCountdown'))$('#timerCountdown').textContent=remaining?String(Math.floor(remaining/3600)).padStart(2,'0')+':'+String(Math.floor(remaining/60)%60).padStart(2,'0')+':'+String(remaining%60).padStart(2,'0'):'—';if(timerEnd&&remaining===0){timerEnd=0;write('luma-timer',0);change({power:false});stopAudio();toast('Таймер завершён · свет выключен')}}
function setControl(c){control=c;$$('[data-control]').forEach(b=>b.classList.toggle('selected',b.dataset.control===c));['color','effects','audio'].forEach(n=>$('#'+n+'Control').hidden=n!==c);update()}
async function initAudio(){audioContext ||= new (window.AudioContext||window.webkitAudioContext)();await audioContext.resume();analyser ||= audioContext.createAnalyser();analyser.fftSize=256;analyser.smoothingTimeConstant=.7}
function stopAudio(){const wasActive=audioActive;analyser?.disconnect();micStream?.getTracks().forEach(t=>t.stop());micStream=null;audioSource?.disconnect();audioSource=null;audioActive=false;audioLevel=0;$('#audioPlayer').pause();$('#micBtn').innerHTML=icon('music')+'Включить микрофон';$$('#audioBars i').forEach(x=>x.style.height='15px');if(wasActive)queueSend()}
$('#micBtn').onclick=async()=>{if(audioActive){stopAudio();queueSend();return}try{if(!navigator.mediaDevices?.getUserMedia)throw new Error('Микрофон доступен через HTTPS или localhost. На ESP8266 выберите аудиофайл.');await initAudio();micStream=await navigator.mediaDevices.getUserMedia({audio:true});audioSource=audioContext.createMediaStreamSource(micStream);audioSource.connect(analyser);audioActive=true;$('#micBtn').innerHTML=icon('music')+'Остановить микрофон';change({effect:'static',scene:'',power:true});toast('Микрофон включён')}catch(e){stopAudio();toast(e.message||'Нет доступа к микрофону')}};
let mediaSource=null,audioObjectURL=null;$('#audioFile').onchange=async e=>{let f=e.target.files[0];if(!f)return;stopAudio();await initAudio();if(audioObjectURL)URL.revokeObjectURL(audioObjectURL);audioObjectURL=URL.createObjectURL(f);const player=$('#audioPlayer');player.src=audioObjectURL;player.hidden=false;mediaSource ||= audioContext.createMediaElementSource(player);mediaSource.disconnect();mediaSource.connect(analyser);analyser.connect(audioContext.destination);audioActive=true;$('#micBtn').innerHTML=icon('music')+'Остановить звук';change({effect:'static',scene:'',power:true});try{await player.play()}catch{toast('Нажмите воспроизведение в плеере')}};$('#audioPlayer').onplay=()=>{audioActive=true};$('#audioPlayer').onpause=()=>{if(!micStream){audioActive=false;queueSend()}};$('#audioPlayer').onended=()=>{audioActive=false;queueSend()};$('#audioPlayer').onerror=()=>{audioActive=false;toast('Этот аудиофайл не поддерживается браузером')};$('#sensitivity').oninput=e=>$('#sensitivityValue').textContent=Number(e.target.value).toFixed(1)+'×';
const frequencies=new Uint8Array(128);let lastFrame=0;function animate(t){requestAnimationFrame(animate);if(t-lastFrame<35)return;lastFrame=t;let color=state.color,b=state.brightness/100;if(audioActive&&analyser){analyser.getByteFrequencyData(frequencies);let sum=0;for(let i=1;i<60;i++)sum+=frequencies[i];audioLevel=Math.min(1,sum/59/180*Number($('#sensitivity').value));b*=.06+.94*audioLevel;$$('#audioBars i').forEach((el,i)=>el.style.height=(6+frequencies[i*5]/255*51)+'px');if(connected&&state.power&&t-lastAudioSend>160&&!requestBusy&&!pendingState){lastAudioSend=t;pendingState={audio:Math.round((.06+.94*audioLevel)*100)};flush()}}else{let phase=t/1000*(.1+state.speed/100);if(state.effect==='breathe')b*=.35+.65*(Math.sin(phase)+1)/2;if(state.effect==='rainbow')color=hsv(phase*32%360);if(state.effect==='candle')b*=.75+.15*Math.sin(phase*13)+.1*Math.sin(phase*23)}if(!state.power)b=0;$('#halo').style.background=color;$('#halo').style.opacity=b*.8;$('#halo').style.filter=`blur(${8+b*45}px)`;$('#halo').style.transform=`scale(${1+b*.42})`}
$('#brightness').oninput=e=>change({brightness:+e.target.value,scene:''});$('#speed').oninput=e=>change({speed:+e.target.value,scene:''});$('#power').onclick=()=>change({power:!state.power});$('#nativeColor').oninput=e=>change({color:e.target.value,scene:'',effect:'static'});$('#hex').oninput=e=>{if(/^#[a-f\d]{6}$/i.test(e.target.value))change({color:e.target.value.toLowerCase(),scene:'',effect:'static'})};$('#hex').onchange=e=>{if(/^#[a-f\d]{6}$/i.test(e.target.value)){change({color:e.target.value.toLowerCase(),scene:'',effect:'static'})}else{e.target.value=state.color.toUpperCase();toast('Цвет должен иметь формат #FF9E57')}};
function wheelSelect(e){const r=$('#colorWheel').getBoundingClientRect();let h=(Math.atan2(e.clientX-r.left-r.width/2,-(e.clientY-r.top-r.height/2))*180/Math.PI+360)%360;change({color:hsv(h),scene:'',effect:'static'})}$('#colorWheel').onpointerdown=e=>{$('#colorWheel').setPointerCapture(e.pointerId);wheelSelect(e)};$('#colorWheel').onpointermove=e=>{if($('#colorWheel').hasPointerCapture(e.pointerId))wheelSelect(e)};$('#colorWheel').onkeydown=e=>{if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key)){e.preventDefault();change({color:hsv((hue(state.color)+(['ArrowLeft','ArrowDown'].includes(e.key)?-5:5)+360)%360),scene:'',effect:'static'})}};
$('#swatches').innerHTML=['#ff9e57','#f4d4a0','#f47493','#a484ff','#729feb','#8ed8bd','#e8eee3'].map(c=>`<button class="swatch" data-color="${c}" style="--swatch:${c}" aria-label="Цвет ${c}"></button>`).join('');$('#effectOptions').innerHTML=effects.map(([id,n])=>`<button class="effect-option" data-effect="${id}">${n}</button>`).join('');$('#audioBars').innerHTML='<i></i>'.repeat(16);
$('#focusBtn').onclick=()=>document.body.classList.toggle('focus-mode');document.addEventListener('keydown',e=>{if(e.key==='Escape')document.body.classList.remove('focus-mode')});$('#uploadArt').onclick=()=>$('#artFile').click();$('#artFile').onchange=e=>{let f=e.target.files[0];if(!f)return;if(!['image/jpeg','image/png','image/webp'].includes(f.type)||f.size>4*1024*1024){toast('Выберите PNG, JPG или WebP до 4 МБ');return}let reader=new FileReader();reader.onload=()=>{const img=new Image();img.onload=()=>{const canvas=document.createElement('canvas');const scale=Math.min(1,900/img.width,1200/img.height);canvas.width=img.width*scale;canvas.height=img.height*scale;canvas.getContext('2d').drawImage(img,0,0,canvas.width,canvas.height);const src=canvas.toDataURL('image/jpeg',.85);$('#artImage').src=src;write('luma-art',src);toast('Ваша картина добавлена')};img.onerror=()=>toast('Не удалось прочитать изображение');img.src=reader.result};reader.readAsDataURL(f)};
$('#addRoom').onclick=()=>openModal('Новая комната','<label class="field">Название<input name="name" required maxlength="25" placeholder="Например, кабинет"></label>',fd=>{let r=fd.get('name').trim();if(!r||rooms.includes(r)||r==='Все комнаты'){toast('Введите новое название комнаты');return false}rooms.push(r);write('luma-rooms',rooms);renderRooms();toast('Комната добавлена')});$('#helpBtn').onclick=()=>showPage('settings');$('#addDevice').onclick=addDevice;$('#saveScene').onclick=saveScene;
document.addEventListener('click',e=>{let b=e.target.closest('button');if(!b)return;if(b.dataset.page)showPage(b.dataset.page);if(b.dataset.control)setControl(b.dataset.control);if(b.dataset.scene)selectScene(b.dataset.scene);if(b.dataset.color)change({color:b.dataset.color,scene:'',effect:'static'});if(b.dataset.effect)change({effect:b.dataset.effect,scene:''});if(b.dataset.minutes)startTimer(+b.dataset.minutes);if(b.dataset.room){selectedRoom=b.dataset.room;renderRooms();if(selectedRoom==='Все комнаты'||selectedRoom===deviceRoom)showPage('light');else{$('#lightPage').hidden=true;$('#otherPage').hidden=false;$('#otherPage').innerHTML=heading(esc(selectedRoom),'В этой комнате пока нет подсветки.')+`<div class="content-panel empty-state">${icon('bulb')}<h2>Добавьте немного света</h2><p>Назначьте подсветку картины этой комнате в настройках.</p><button class="button primary" data-page="settings">Настроить устройство</button></div>`}}if(b.dataset.deleteCamera){cameras=cameras.filter(c=>c.id!==+b.dataset.deleteCamera);write('luma-cameras',cameras);showPage('cameras');toast('Камера удалена из приложения')}if(b.dataset.deleteScene){customScenes=customScenes.filter(s=>s.id!==b.dataset.deleteScene);write('luma-scenes',customScenes);renderScenes($('#sceneGrid'));showPage('scenes')}});
$('#pictureWrap').addEventListener('pointermove',e=>{if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;const r=e.currentTarget.getBoundingClientRect();e.currentTarget.style.transform=`perspective(900px) rotateY(${(e.clientX-r.left-r.width/2)/30}deg) rotateX(${-(e.clientY-r.top-r.height/2)/40}deg)`});$('#pictureWrap').onpointerleave=e=>e.currentTarget.style.transform='perspective(900px) rotateY(-3deg)';
let savedArt=read('luma-art',null);if(savedArt)$('#artImage').src=savedArt;renderRooms();renderScenes($('#sceneGrid'));update();renderConnection();updateTimer();setInterval(updateTimer,1000);requestAnimationFrame(animate);if(connection.mode!=='demo'){timerEnd=0;connect();}document.addEventListener('visibilitychange',()=>{if(document.hidden&&micStream){stopAudio();queueSend()}});window.addEventListener('pagehide',()=>{micStream?.getTracks().forEach(t=>t.stop())});
